class Solution {
public:
    int countConsistent(vector<int>& nums) {
        int n = (int)nums.size();
        if (n == 0) return 0;
        const int B = 7; // nums[i] <= 100 < 128
        vector<int> leftZero(n), rightZero(n);
        vector<int> lastZero(B, -1), nextZero(B, n);
        for (int i = 0; i < n; i++) {
            int lz = -1;
            for (int b = 0; b < B; b++) {
                if ((nums[i] >> b) & 1) lz = max(lz, lastZero[b]);
            }
            leftZero[i] = lz;
            for (int b = 0; b < B; b++) {
                if (!((nums[i] >> b) & 1)) lastZero[b] = i;
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            int rz = n;
            for (int b = 0; b < B; b++) {
                if ((nums[i] >> b) & 1) rz = min(rz, nextZero[b]);
            }
            rightZero[i] = rz;
            for (int b = 0; b < B; b++) {
                if (!((nums[i] >> b) & 1)) nextZero[b] = i;
            }
        }
        vector<int> leftMin(n), rightMin(n);
        vector<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
            leftMin[i] = st.empty() ? -1 : st.back();
            st.push_back(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && nums[st.back()] > nums[i]) st.pop_back();
            rightMin[i] = st.empty() ? n : st.back();
            st.push_back(i);
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int L = max(leftMin[i] + 1, leftZero[i] + 1);
            int R = min(rightMin[i] - 1, rightZero[i] - 1);
            if (L <= i && i <= R) {
                ans += (long long)(i - L + 1) * (R - i + 1);
            }
        }
        return (int)ans;
    }
};
